export const getSessionActionUrl = (id: number,) => {




  return `/api/sessions/${id}/actions`
}

/**
 * @summary Apply a human action to a session
 */
export const sessionAction = async (id: number,
    sessionActionBody: SessionAction, options?: Parameters<typeof customFetch>[1]): Promise<SessionSummary> => {

  return customFetch<SessionSummary>(getSessionActionUrl(id),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(sessionActionBody)
  }
);}





