    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof sessionAction>>, TError,SessionActionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof sessionAction>>, TError,SessionActionMutationVariables, TContext> => {

const mutationKey = getSessionActionMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof sessionAction>>, SessionActionMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  sessionAction(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

